export function composeMiddleware(middlewares: Middleware[]): Middleware {
  return function composedMiddleware(event: H3Event, next: () => unknown | Promise<unknown>) {
    let index = 0;
    let nextCalled = false;
    let nextResult: unknown;

    const callNext = () => {
      if (nextCalled) {
        return nextResult;
      }
      nextCalled = true;
      if (index === middlewares.length) {
        return next();
      }
      const fn = middlewares[index++];
      const ret = fn(event, callNext);
      if (isUnhandledResponse(ret)) {
        return callNext();
      }
      if (typeof (ret as PromiseLike<unknown>)?.then === "function") {
        return (ret as PromiseLike<unknown>).then((resolved) => {
          if (isUnhandledResponse(resolved)) {
            return callNext();
          }
          return resolved;
        });
      }
      return ret;
    };

    return callNext();
  };
}

